    if not fours or not sixes:
        return out

    fr0, fr1 = min(r for r, c in fours), max(r for r, c in fours)
    fc0, fc1 = min(c for r, c in fours), max(c for r, c in fours)
    sr0, sr1 = min(r for r, c in sixes), max(r for r, c in sixes)
    sc0, sc1 = min(c for r, c in sixes), max(c for r, c in sixes)

    # Select the direction in which the marker lies beyond the 4-shape.
    vertical_gap = sr0 - fr1 - 1 if sr0 > fr1 else fr0 - sr1 - 1 if sr1 < fr0 else 10**6
    horizontal_gap = sc0 - fc1 - 1 if sc0 > fc1 else fc0 - sc1 - 1 if sc1 < fc0 else 10**6

    for r, c in sixes:
        out[r][c] = 0

    if vertical_gap <= horizontal_gap:
        if sr0 > fr1:
            reflected = ((2 * fr1 + 1 - r, c) for r, c in fours)
        else:
            reflected = ((2 * fr0 - 1 - r, c) for r, c in fours)
    else:
        if sc0 > fc1:
            reflected = ((r, 2 * fc1 + 1 - c) for r, c in fours)
        else:
            reflected = ((r, 2 * fc0 - 1 - c) for r, c in fours)

    for r, c in reflected:
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = 4
    return out
